import React from 'react';
import { Link } from 'react-router-dom';
import Breadcrumbs from '../components/Breadcrumbs';
import { getProductsByCategoryAndSubcategory } from '../data/products';
import './1.css'

const ReactionResinsPage = () => {
  const breadcrumbItems = [
    { label: 'Продукти', link: '/products' },
    { label: 'Реакційні смоли' }
  ];

  const primerProducts = getProductsByCategoryAndSubcategory('reaction-resins', 'primer-binder');
  const mortarProducts = getProductsByCategoryAndSubcategory('reaction-resins', 'mortar');
  const groutProducts = getProductsByCategoryAndSubcategory('reaction-resins', 'grout');
  const applicationAidsProducts = getProductsByCategoryAndSubcategory('reaction-resins', 'application-aids');

  return (
    <>
      <Breadcrumbs items={breadcrumbItems} />
      <div className="site-inner">
        <div className="wrap">
          <div className="content-sidebar-wrap">
            <main className="content">
              <article className="entry">
                <div className="entry-content">
                  <h1>Реакційні смоли</h1>
                  <p>
                    Окрім відомих мінеральних розчинів для заливання та ремонту, PAGEL
                    пропонує рідкі пластики на основі епоксидної смоли для промислових
                    застосувань та захисту поверхонь. Захист бетону, адгезійні мости
                    та спеціальні ґрунтовки (наприклад, для поверхонь, забруднених
                    оливою, або вологих основ) — лише частина доступної програми
                    продуктів.
                  </p>

                  <div style={{ marginTop: 30 }}>
                    <h2>Епоксидна ґрунтовка/сполучний матеріал:</h2>
                    <ul>
                      {primerProducts.map(p => (
                        <li key={p.id}><Link to={`/products/reaction-resins/${p.slug}`}>{p.title}</Link></li>
                      ))}
                    </ul>
                  </div>

                  <div style={{ marginTop: 30 }}>
                    <h2>Епоксидний розчин:</h2>
                    <ul>
                      {mortarProducts.map(p => (
                        <li key={p.id}><Link to={`/products/reaction-resins/${p.slug}`}>{p.title}</Link></li>
                      ))}
                    </ul>
                  </div>

                  <div style={{ marginTop: 30 }}>
                    <h2>Епоксидний розчин для заливання:</h2>
                    <ul>
                      {groutProducts.map(p => (
                        <li key={p.id}><Link to={`/products/reaction-resins/${p.slug}`}>{p.title}</Link></li>
                      ))}
                    </ul>
                  </div>

                  <div style={{ marginTop: 30 }}>
                    <h2>Допоміжні засоби для нанесення:</h2>
                    <ul>
                      {applicationAidsProducts.map(p => (
                        <li key={p.id}><Link to={`/products/reaction-resins/${p.slug}`}>{p.title}</Link></li>
                      ))}
                    </ul>
                  </div>
                </div>
              </article>
            </main>
          </div>
        </div>
      </div>
    </>
  );
};

export default ReactionResinsPage;
